      "path": "archify/renderers/shared/repository-evidence.mjs",
      "content": "import { spawnSync } from 'node:child_process';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { throwDiagnosticError, withDiagnosticRecordingSuppressed } from './diagnostics.mjs';\nimport { sameEntry } from './path-semantics.mjs';\nimport { parseRepositoryRemote, redactRepositoryRemote, repositorySourceHref, repositoryTreeHref } from './repository-location.mjs';\n\nconst FULL_SHA_RE = /^[a-f0-9]{40}$/i;\nconst CONTROL_CHARACTER_RE = /[\\u0000-\\u001f\\u007f]/;\nconst MAX_SOURCE_BYTES = 16 * 1024 * 1024;\n\nfunction evidenceFailure(code, message, { subject = {}, evidence = {}, supportedFixes = [] } = {}) {\n  throwDiagnosticError(message, [{\n    code,\n    severity: 'error',\n    message,\n    subject: { surface: 'repository-evidence', ...subject },\n    evidence,\n    supportedFixes,\n  }]);\n}\n\nfunction runGit(repoRoot, args) {\n  // 固定 SHA 的来源必须读取原始对象，不能使用本地 replacement refs 的替换内容。\n  const result = spawnSync('git', ['--no-replace-objects', '-C', repoRoot, ...args], {\n    encoding: 'utf8',\n    maxBuffer: MAX_SOURCE_BYTES,\n    // Older Git may ignore NO_LAZY_FETCH; no transport is needed for local reads.\n    env: { ...process.env, GIT_NO_LAZY_FETCH: '1', GIT_ALLOW_PROTOCOL: '' },\n  });\n  if (result.error) evidenceFailure('repository-evidence/git-unavailable', `Could not run Git: ${result.error.message}`, {\n    evidence: { reason: result.error.message },\n    supportedFixes: ['install Git and ensure it is available on PATH'],\n  });\n  return result;\n}\n\n// Check types in one session, then read only blobs whose cited lines need\n// verification. Path-only references never require loading the file contents.\nfunction prefetchBlobs(repoRoot, objectNeedsContent) {\n  const blobs = readBatchObjects(repoRoot, [...objectNeedsContent.keys()], false);\n  if (!blobs) return null;\n  const readable = [...objectNeedsContent].filter(([object, needsContent]) => {\n    const blob = blobs.get(object);\n    return needsContent && blob?.type === 'blob' && blob.size <= MAX_SOURCE_BYTES;\n  }).map(([object]) => object);\n  const contents = readBatchObjects(repoRoot, readable, true);\n  if (contents) for (const [object, blob] of contents) blobs.set(object, blob);\n  // Failed or oversized reads fall back in source order to the original\n  // per-file path, preserving its size limit and diagnostic behavior.\n  return blobs;\n}\n\nfunction readBatchObjects(repoRoot, objects, includeContent) {\n  if (!objects.length) return new Map();\n  const mode = includeContent ? '--batch' : '--batch-check';\n  const result = spawnSync('git', ['--no-replace-objects', '-C', repoRoot, 'cat-file', mode], {\n    input: objects.join('\\n') + '\\n',\n    maxBuffer: 64 * 1024 * 1024,\n    env: { ...process.env, GIT_NO_LAZY_FETCH: '1', GIT_ALLOW_PROTOCOL: '' },\n  });\n  if (result.error || result.status !== 0 || !Buffer.isBuffer(result.stdout)) return null;\n  const buffer = result.stdout;\n  const blobs = new Map();\n  let cursor = 0;\n  for (const object of objects) {\n    const newline = buffer.indexOf(0x0a, cursor);\n    if (newline < 0) return null;\n    const header = buffer.toString('utf8', cursor, newline);\n    cursor = newline + 1;\n    if (header.endsWith(' missing')) {\n      blobs.set(object, { missing: true });\n      continue;\n    }\n    const parts = header.split(' ');\n    const size = Number(parts[2]);\n    if (parts.length !== 3 || !Number.isSafeInteger(size) || size < 0) return null;\n    const blob = { type: parts[1], size };\n    if (includeContent) {\n      if (cursor + size >= buffer.length || buffer[cursor + size] !== 0x0a) return null;\n      blob.content = buffer.toString('utf8', cursor, cursor + size);\n      cursor += size + 1;\n    }\n    blobs.set(object, blob);\n  }\n  return blobs;\n}\n\nfunction gitValue(repoRoot, args, failure) {\n  const result = runGit(repoRoot, args);\n  if (result.status !== 0) evidenceFailure('repository-evidence/git-command', failure, {\n    evidence: { gitArgs: args, exitCode: result.status },\n    supportedFixes: ['use the intended local Git repository and verify its origin and revision'],\n  });\n  // Remove Git's record terminator without changing whitespace in a path.\n  return result.stdout.replace(/\\n$/, '');\n}\n\nfunction verifiedSourcePath(value, where) {\n  const sourcePath = String(value || '');\n  // path-contract-allow: git-path -- Git tree entries use repository-relative POSIX syntax.\n  if (!sourcePath || sourcePath.startsWith('/') || sourcePath.includes('\\\\') || CONTROL_CHARACTER_RE.test(sourcePath)) {\n    evidenceFailure('repository-evidence/path-invalid', `${where} must be a repo-relative POSIX path.`, {\n      subject: { path: where },\n      evidence: { authoredPath: sourcePath },\n      supportedFixes: ['use a repository-relative path with forward slashes'],\n    });\n  }\n  const segments = sourcePath.split('/');\n  if (segments.some((segment) => !segment || segment === '.' || segment === '..') || segments[0] === '.git') {\n    evidenceFailure('repository-evidence/path-escape', `${where} must stay inside the repository and may not address .git.`, {\n      subject: { path: where },\n      evidence: { authoredPath: sourcePath },\n      supportedFixes: ['remove empty, dot, parent, or .git path segments'],\n    });\n  }\n  return segments.join('/');\n}\n\nfunction sourceLineCount(content) {\n  if (!content.length) return 0;\n  const lines = content.split(/\\r\\n|\\n|\\r/);\n  return lines.length - (/(?:\\r\\n|\\n|\\r)$/.test(content) ? 1 : 0);\n}\n\n// Every diagram type carries its nodes under a different property name, and\n// source evidence is authored on those nodes. One table keeps the verification\n// below identical for all five types instead of branching per type: the only\n// per-type fact is which array to read and which JSON pointer to quote back.\nconst EVIDENCE_NODE_COLLECTIONS = {\n  architecture: 'components',\n  workflow: 'nodes',\n  sequence: 'participants',\n  dataflow: 'nodes',\n  lifecycle: 'states',\n  erd: 'entities',\n  tree: 'nodes',\n  class: 'types',\n  timeline: 'events',\n  waterfall: 'spans',\n};\n\nfunction evidenceNodes(diagramType, diagram) {\n  const collection = EVIDENCE_NODE_COLLECTIONS[diagramType];\n  if (!collection) return null;\n  return { collection, nodes: Array.isArray(diagram?.[collection]) ? diagram[collection] : [] };\n}\n\nexport function hasRepositoryEvidence(diagramType, diagram) {\n  const authored = evidenceNodes(diagramType, diagram);\n  if (!authored) return false;\n  return Boolean(diagram?.meta?.repository) || authored.nodes.some((node) => Array.isArray(node?.sources) && node.sources.length);\n}\n\nexport function verifyRepositoryEvidence(diagramType, diagram, repoRootInput) {\n  if (!hasRepositoryEvidence(diagramType, diagram)) return null;\n  const { collection, nodes: authoredNodes } = evidenceNodes(diagramType, diagram);\n\n  const repository = diagram.meta?.repository;\n  if (!repository) evidenceFailure('repository-evidence/repository-required', 'Repository evidence requires /meta/repository.', {\n    subject: { path: '/meta/repository', diagramType, collection },\n    supportedFixes: [`add the pinned repository metadata or remove /${collection} sources`],\n  });\n  if (!FULL_SHA_RE.test(repository.revision || '')) {\n    evidenceFailure('repository-evidence/revision-invalid', '/meta/repository/revision must be a full 40-character commit SHA.', {\n      subject: { path: '/meta/repository/revision' },\n      evidence: { revision: repository.revision },\n      supportedFixes: ['pin one full 40-character commit SHA'],\n    });\n  }\n  const location = parseRepositoryRemote(repository.url, { authored: true, provider: repository.provider });\n  if (!location) {\n    // A filesystem path is the common authoring mistake: the field carries the\n    // remote origin identity, which `git remote get-url origin` reports.\n    const filesystemPath = /^(?:[\\\\/]|~|\\.{1,2}(?:[\\\\/]|$)|[A-Za-z]:[\\\\/])/.test(String(repository.url ?? ''));\n    evidenceFailure('repository-evidence/url-invalid', '/meta/repository/url must be a credential-free HTTP(S) or Git SSH repository address without query, fragment, or dot segments.', {\n      subject: { path: '/meta/repository/url' },\n      evidence: filesystemPath ? { authoredValueLooksLike: 'local filesystem path; the expected value is the remote origin address' } : {},\n      supportedFixes: ['run `git remote get-url origin` inside --repo-root and declare that credential-free address', 'use link_mode: local-only for internal repositories'],\n    });\n  }\n  const linkMode = repository.link_mode ?? 'web';\n  if (!['web', 'local-only'].includes(linkMode)) evidenceFailure('repository-evidence/link-mode-invalid', 'Repository link_mode must be web or local-only.');\n  if (repository.provider !== undefined && (!['github', 'gitee', 'gitlab'].includes(repository.provider) || repository.provider !== location.provider)) {\n    evidenceFailure('repository-evidence/provider-invalid', 'Repository provider must match its supported public host (github.com, gitee.com or gitlab.com); gitlab also names a self-managed GitLab host.', {\n      subject: { path: '/meta/repository/provider' },\n      supportedFixes: ['use the matching provider or omit provider and select link_mode: local-only'],\n    });\n  }\n  // GitLab projects may sit in nested groups; GitHub and Gitee are owner/repository.\n  const webPath = location.provider === 'gitlab' ? /^[A-Za-z0-9_.-]+(?:\\/[A-Za-z0-9_.-]+)+$/ : /^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/;\n  if (linkMode === 'web' && (!location.provider || location.protocol !== 'https:' || location.endpoint !== 'standard' || !webPath.test(location.path))) {\n    evidenceFailure('repository-evidence/links-unsupported', 'Web source links require a canonical GitHub, Gitee, or GitLab HTTPS repository URL.', {\n      subject: { path: '/meta/repository/url' },\n      supportedFixes: ['use a canonical GitHub, Gitee, or GitLab HTTPS URL; declare provider: gitlab for a self-managed GitLab host', 'select link_mode: local-only to retain local verification without web links'],\n    });\n  }\n  if (!repoRootInput) {\n    evidenceFailure('repository-evidence/root-required', 'This diagram declares source evidence. Pass --repo-root <repository> so Archify can verify it before rendering.', {\n      subject: { path: '/meta/repository' },\n      supportedFixes: ['pass --repo-root with the matching local Git checkout'],\n    });\n  }\n\n  const requestedRoot = path.resolve(repoRootInput);\n  let realRoot;\n  try {\n    realRoot = fs.realpathSync(requestedRoot);\n  } catch (error) {\n    evidenceFailure('repository-evidence/root-unreadable', `Could not resolve evidence repository root \"${requestedRoot}\": ${error.message}`, {\n      subject: { repoRoot: requestedRoot },\n      evidence: { reason: error.message },\n      supportedFixes: ['pass one readable local repository directory'],\n    });\n  }\n  const gitRoot = gitValue(realRoot, ['rev-parse', '--show-toplevel'], `Evidence root \"${realRoot}\" is not a Git repository.`);\n  const rootIdentity = sameEntry(realRoot, gitRoot);\n  if (rootIdentity.status === 'unknown') {\n    evidenceFailure('repository-evidence/root-identity-indeterminate', 'Could not determine whether the evidence root is the Git top-level directory.', {\n      subject: { repoRoot: realRoot },\n      evidence: { gitTopLevel: gitRoot, relation: rootIdentity.reason },\n      supportedFixes: ['pass the readable Git top-level directory using its canonical filesystem path'],\n    });\n  }\n  if (rootIdentity.status === 'different') {\n    evidenceFailure('repository-evidence/root-not-top-level', `Evidence root must be the Git top-level directory: ${gitRoot}`, {\n      subject: { repoRoot: realRoot },\n      evidence: { gitTopLevel: gitRoot },\n      supportedFixes: [`pass --repo-root ${gitRoot}`],\n    });\n  }\n  const origin = gitValue(realRoot, ['remote', 'get-url', 'origin'], 'Evidence repository must have an origin remote.').trim();\n  if (parseRepositoryRemote(origin, { provider: repository.provider })?.identity !== location.identity) {\n    const safeOrigin = redactRepositoryRemote(origin);\n    evidenceFailure('repository-evidence/origin-mismatch', `Evidence repository origin ${JSON.stringify(safeOrigin)} does not match ${JSON.stringify(repository.url)}.`, {\n      subject: { repoRoot: realRoot },\n      evidence: { localOrigin: safeOrigin, authoredRepository: repository.url },\n      supportedFixes: ['use the matching local checkout or correct the authored repository URL'],\n    });\n  }\n\n  const revision = repository.revision.toLowerCase();\n  const commit = runGit(realRoot, ['cat-file', '-e', `${revision}^{commit}`]);\n  if (commit.status !== 0) {\n    evidenceFailure('repository-evidence/revision-unavailable', `Evidence revision ${revision} is not available in the local repository.`, {\n      subject: { repoRoot: realRoot },\n      evidence: { revision },\n      supportedFixes: ['fetch the pinned commit or pin an available full commit SHA'],\n    });\n  }\n\n  // The batch is an optimization only: every path, line-range, file and line\n  // check still runs in source order in the verification loop below, so a\n  // citation the batch cannot answer for never reorders the diagnostics.\n  const citedObjects = new Map();\n  for (const [nodeIndex, node] of authoredNodes.entries()) {\n    if (!Array.isArray(node.sources) || node.sources.length === 0) continue;\n    for (const [sourceIndex, authored] of node.sources.entries()) {\n      const at = `/${collection}/${nodeIndex}/sources/${sourceIndex}`;\n      let sourcePath;\n      try {\n        sourcePath = withDiagnosticRecordingSuppressed(() => verifiedSourcePath(authored.path, `${at}/path`));\n      } catch {\n        continue;\n      }\n      const object = `${revision}:${sourcePath}`;\n      citedObjects.set(object, citedObjects.get(object) || Boolean(authored.line));\n    }\n  }\n  const prefetchedBlobs = prefetchBlobs(realRoot, citedObjects);\n\n  const nodes = Object.create(null);\n  const sourceDiagnostics = [];\n  let referenceCount = 0;\n  for (const [nodeIndex, node] of authoredNodes.entries()) {\n    if (!Array.isArray(node.sources) || node.sources.length === 0) continue;\n    // `componentId` shipped with the architecture-only path; keep it beside the\n    // type-neutral `nodeId` so existing agent handling stays valid.\n    const nodeSubject = collection === 'components'\n      ? { diagramType, collection, nodeId: node.id, componentId: node.id }\n      : { diagramType, collection, nodeId: node.id };\n    const verified = [];\n    for (const [sourceIndex, authored] of node.sources.entries()) {\n      const at = `/${collection}/${nodeIndex}/sources/${sourceIndex}`;\n      const where = `${at}/path`;\n      try {\n        const source = {\n          path: verifiedSourcePath(authored.path, where),\n          ...(authored.line ? { line: authored.line } : {}),\n          ...(authored.end_line ? { endLine: authored.end_line } : {}),\n          ...(authored.label ? { label: authored.label } : {}),\n        };\n        if (source.endLine && !source.line) {\n          evidenceFailure('repository-evidence/line-required', `${at}/end_line requires line.`, {\n            subject: { path: `${at}/end_line`, ...nodeSubject },\n            supportedFixes: ['add line or remove end_line'],\n          });\n        }\n        if (source.endLine && source.endLine < source.line) {\n          evidenceFailure('repository-evidence/line-range-invalid', `${at}/end_line must be greater than or equal to line.`, {\n            subject: { path: at, ...nodeSubject },\n            evidence: { line: source.line, endLine: source.endLine },\n            supportedFixes: ['use an end_line greater than or equal to line'],\n          });\n        }\n        const object = `${revision}:${source.path}`;\n        const prefetched = prefetchedBlobs ? prefetchedBlobs.get(object) : undefined;\n        const objectIsBlob = prefetched\n          ? !prefetched.missing && prefetched.type === 'blob'\n          : (() => {\n            const type = runGit(realRoot, ['cat-file', '-t', object]);\n            return type.status === 0 && type.stdout.trim() === 'blob';\n          })();\n        if (!objectIsBlob) {\n          // A promisor blob can exist in the pinned tree without being stored\n          // locally. Do not tell the caller to change a correct source path.\n          const tree = runGit(realRoot, ['ls-tree', '-z', revision, '--', source.path]);\n          const knownBlob = tree.status === 0 && tree.stdout.split('\\0').some((entry) => {\n            const separator = entry.indexOf('\\t');\n            return entry.slice(separator + 1) === source.path\n              && /^\\d+ blob [a-f0-9]+$/.test(entry.slice(0, separator));\n          });\n          if (knownBlob) {\n            evidenceFailure('repository-evidence/object-unavailable', `${where} exists at revision ${revision}, but its content is unavailable in the local repository.`, {\n              subject: { path: where, ...nodeSubject },\n              evidence: { sourcePath: source.path, revision },\n              supportedFixes: ['explicitly fetch the pinned source objects into the local checkout, then retry verification'],\n            });\n          }\n          evidenceFailure('repository-evidence/file-missing', `${where} does not identify a file at revision ${revision}.`, {\n            subject: { path: where, ...nodeSubject },\n            evidence: { sourcePath: source.path, revision },\n            supportedFixes: ['use a file path that exists at the pinned revision'],\n          });\n        }\n        if (source.line) {\n          const content = prefetched && Object.hasOwn(prefetched, 'content')\n            ? { status: 0, stdout: prefetched.content }\n            : runGit(realRoot, ['show', object]);\n          if (content.status !== 0) evidenceFailure('repository-evidence/file-unreadable', `${where} could not be read at revision ${revision}.`, {\n            subject: { path: where, ...nodeSubject },\n            evidence: { sourcePath: source.path, revision },\n            supportedFixes: ['verify the pinned blob is readable in the local checkout'],\n          });\n          const lineCount = sourceLineCount(content.stdout);\n          const requestedLine = source.endLine || source.line;\n          if (requestedLine > lineCount) {\n            evidenceFailure('repository-evidence/line-out-of-range', `${at} requests line ${requestedLine}, but ${source.path} has ${lineCount} lines at revision ${revision}.`, {\n              subject: { path: at, ...nodeSubject },\n              evidence: { sourcePath: source.path, requestedLine, lineCount, revision },\n              supportedFixes: ['use a line range that exists at the pinned revision'],\n            });\n          }\n        }\n        verified.push({ ...source, ...(linkMode === 'web' ? { href: repositorySourceHref(location.provider, location.url, revision, source) } : {}) });\n        referenceCount += 1;\n      } catch (error) {\n        // Independent citations can be repaired together. Keep the first\n        // diagnostic and source order; an invalid reference never verifies.\n        if (!error?.archifyDiagnostics?.length) throw error;\n        sourceDiagnostics.push(...error.archifyDiagnostics);\n        // An unavailable Git process or an oversized read is not a bad\n        // citation. Stop rather than repeat that failure for every source.\n        if (error.archifyDiagnostics.some(({ code }) => code === 'repository-evidence/git-unavailable')) {\n          throwDiagnosticError(sourceDiagnostics[0].message, sourceDiagnostics);\n        }\n      }\n    }\n    nodes[node.id] = verified;\n  }\n  if (sourceDiagnostics.length) {\n    throwDiagnosticError(sourceDiagnostics[0].message, sourceDiagnostics);\n  }\n  if (referenceCount === 0) {\n    evidenceFailure('repository-evidence/source-required', `/meta/repository requires at least one /${collection} source reference.`, {\n      subject: { path: '/meta/repository', diagramType, collection },\n      supportedFixes: [`add at least one verified /${collection} source or remove repository metadata`],\n    });\n  }\n\n  return {\n    schemaVersion: 1,\n    verified: true,\n    repository: {\n      url: location.url,\n      revision,\n      shortRevision: revision.slice(0, 7),\n      label: location.provider === 'github' ? location.path : location.url.replace(/^(?:https?:\\/\\/|ssh:\\/\\/git@|git@)/, ''),\n      ...(linkMode === 'web' ? { href: repositoryTreeHref(location.provider, location.url, revision) } : { linkMode }),\n    },\n    referenceCount,\n    nodes,\n  };\n}\n"
    },
    {
      "path": "archify/references/repository-authoring.md",
      "content": "# Repository-backed authoring\n\nUse this reference when a diagram of any type must explain a real repository. The source is\nthe authority for responsibilities, calls, boundaries, and persistence. The\ndiagram is complete when the requested meaning is covered and every asserted\nfact has supporting source evidence.\n\n## Explore on demand\n\n1. **Freeze identity.** From the target repository, record `git rev-parse\n   HEAD`, `git remote get-url origin`, and `git status --short`. Remove HTTP(S)\n   userinfo (including usernames, passwords, and tokens) before recording the\n   origin or placing it in the candidate. Preserve its transport, port, path and\n   `.git` suffix; do not rewrite an internal SSH origin as HTTPS. Pin the credential-free URL and\n   forty-character revision in `meta.repository`. Use `link_mode: \"local-only\"`\n   for an SSH origin, unsupported forge, intentionally local-only source links,\n   or a local fixture whose HTTPS URL is only a repository identity; retain the\n   URL and revision. Web links require a supported GitHub, Gitee, or GitLab HTTPS\n   origin; GitHub, Gitee, gitlab.com, and a self-managed GitLab host declared with\n   `provider: \"gitlab\"` match their SSH origin on the same host. If the\n   worktree is dirty, note the changed paths in your reply; the candidate has no field for them. Repository evidence is verified\n   against committed bytes at the pinned revision, not working-tree edits:\n   inspect a clean checkout at that revision for any cited changed path. Do not\n   present uncommitted bytes as evidence for `HEAD`; `local-only` does not record\n   a verifiable snapshot of those bytes.\n\n2. **Map the slice.** Use project instructions, manifests, entry points,\n   registrations, and deployment configuration to locate candidate runtime\n   units. Read the entry, configuration, and modules relevant to the request.\n   Follow imports and call sites\n   until the requested responsibility reaches its actual input, output, or\n   side effect. Read a small connected slice instead of scanning the repository\n   for a convenient label.\n\n3. **Trace ownership.** Derive runtime and I/O relationships from the observed\n   actor, operation, and target at their call sites; deployment and trust\n   relationships use the corresponding configuration or enforcement evidence. Distinguish the controller requesting\n   an operation from the runtime that executes it and the store receiving bytes.\n   For a file or database edge, the source must identify its actual reader or\n   writer; a responsibility statement such as “maintains tasks” does not prove\n   direct I/O. Keep these facts with the source locations while reading, without\n   a separate planning artifact. Choose which distinctions need separate\n   nodes using [Composition and meaning](authoring-defaults.md#composition-and-meaning);\n   discovering an implementation role does not automatically add it to the overview.\n   A configured provider, an injected adapter, a local stub, and a durable\n   service are different claims; label the one the source supports.\n\n4. **Record evidence while reading.** Keep exact repository-relative paths and\n   inclusive line ranges for each component and meaningful relationship. Follow\n   actual branches, retries, fallbacks, and error handling. A function that is\n   exported or configured but never called by the normal path is an optional\n   capability, not a required runtime edge. For a claim about authoritative\n   state change or control ownership, trace to the actual write or execution\n   site and the conditions that permit it; an upstream caller alone does not\n   establish those conditions.\n\n5. **Name uncertainty.** Write unresolved questions beside the claim they\n   affect: for example, “`writeFile` is called here; durability is unknown.”\n   Resolve a question by reading the next relevant source range or preserve it\n   as an explicit unknown. Never turn a label, package description, or config\n   value into an unobserved service or behavior.\n\nStop exploring when every requested responsibility, relationship, and boundary\nhas supporting source entailment and the remaining unknowns cannot change that\ncoverage. There is no node, edge, citation, view, card, or boundary count to\nhit. Do not add a summary step merely to signal completion.\n\nBatch independent relevant files when known. Read source excerpts with their original\nline numbers (for example, `nl -ba <file> | sed -n '40,90p'`). Copy citation\nstart and end lines from the displayed source, including the actual final line\nwhen an excerpt reaches EOF. Each additional read should answer\nan unresolved question that can change the diagram. Reuse concise facts and\ntheir source ranges already verified in this task; across revisions, recheck\nthe affected entry points, configuration, dependencies, and evidence.\n\n## Evidence by diagram type\n\nOnly the primary elements carry `sources`, at most three ranges each:\nArchitecture components, Workflow, Dataflow and Tree nodes, Sequence\nparticipants, Lifecycle states, ERD entities, Class types, Timeline events and\nWaterfall spans. Relationships, messages, flows and transitions have none: cite\nthe call, write or transition site on the element that owns it (the caller, the\nwriter, the state being left) and keep further evidence in a note or card. A\nfolder node cites its own README or entry file, or else the file that defines\nor runs it. A Timeline event cites a file at the pinned revision that records\nit, such as a changelog entry, and takes its time from a tag or commit in that\nhistory, or noon local time for a date-only record. A tag or commit outside\nthat history is not citable. Say either in a card. A Waterfall without a\nrecorded trace uses `meta.evidence: \"illustrative\"` and keeps its durations\nlabelled as such; do not run the project only to time it.\n\n## Choose an example by structure\n\nSelect the main example in the [Type router](../SKILL.md#type-router) before\nloading its content, using the request and repository metadata already needed\nfor source inspection. Selection fits the existing read batch and needs no extra\nmessage, command, or repository-wide scan. For mixed or unclear tasks, use the\nrequested responsibilities and entry points as they become known in normal\ninspection; keep their actual roles. Read another example when a necessary\ncapability remains unexplained. Examples teach shape, not facts: a library need\nnot acquire filesystem nodes, and finished showcases still follow the\nfirst-draft automatic-routing rule.\n\n## Author from evidence\n\nUse the mode's complete JSON shape, including repository identity,\ncomponents, and connections; every repository-backed component needs supporting source\nreferences, while boundaries or cards are added only when they\nanswer a real reader question. Let automatic routes and automatic\nviewBox sizing work first. Keep the primary path readable, put exception paths\nbeside their owner, and leave filesystem stores outside a control boundary when\nthe source shows a separate responsibility.\n\nAn existing example teaches field shape, not facts or arbitrary values. It does\nnot authorize a new boundary kind, a long note, a viewBox size, or a route\ncontrol. Consult the specific mode schema and `schemas/common.schema.json`\nwhether or not the selected example already contains the field; use the\nschema's enum, length, identifier, and repository rules. Architecture\nboundaries currently use `kind: \"region\"` or `kind: \"security-group\"`; source\nreferences use `path`, `line`, and optional `end_line`.\n\nRepository-backed components need concise, truthful `sources` references. Preserve\ncontrol ownership when summarizing filesystem I/O: the code that reads or writes\na file owns that action, while a pure in-memory transform receives and returns\nvalues. This fact-check does not require a separate overview node for every helper. Use the existing examples for valid field shape, then replace all\nidentifiers, wording, source paths, and claims with inspected repository facts.\n"
    },
